unsafe extern "C" fn get_osabi_name(
    mut filedata: *mut Filedata,
    mut osabi: ::core::ffi::c_uint,
) -> *const ::core::ffi::c_char {
    static mut buff: [::core::ffi::c_char; 32] = [0; 32];
    match osabi {
        0 => return b"UNIX - System V\0".as_ptr() as *const ::core::ffi::c_char,
        1 => return b"UNIX - HP-UX\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_NETBSD => {
            return b"UNIX - NetBSD\0".as_ptr() as *const ::core::ffi::c_char;
        }
        3 => return b"UNIX - GNU\0".as_ptr() as *const ::core::ffi::c_char,
        6 => return b"UNIX - Solaris\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_AIX => return b"UNIX - AIX\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_IRIX => return b"UNIX - IRIX\0".as_ptr() as *const ::core::ffi::c_char,
        9 => return b"UNIX - FreeBSD\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_TRU64 => return b"UNIX - TRU64\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_MODESTO => {
            return b"Novell - Modesto\0".as_ptr() as *const ::core::ffi::c_char;
        }
        ELFOSABI_OPENBSD => {
            return b"UNIX - OpenBSD\0".as_ptr() as *const ::core::ffi::c_char;
        }
        13 => return b"VMS - OpenVMS\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_NSK => {
            return b"HP - Non-Stop Kernel\0".as_ptr() as *const ::core::ffi::c_char;
        }
        ELFOSABI_AROS => return b"AROS\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_FENIXOS => return b"FenixOS\0".as_ptr() as *const ::core::ffi::c_char,
        ELFOSABI_CLOUDABI => {
            return b"Nuxi CloudABI\0".as_ptr() as *const ::core::ffi::c_char;
        }
        ELFOSABI_OPENVOS => {
            return b"Stratus Technologies OpenVOS\0".as_ptr() as *const ::core::ffi::c_char;
        }
        ELFOSABI_CUDA => return b"CUDA\0".as_ptr() as *const ::core::ffi::c_char,
        _ => {
            if osabi >= 64 as ::core::ffi::c_uint {
                match (*filedata).file_header.e_machine as ::core::ffi::c_int {
                    EM_AMDGPU => match osabi {
                        64 => {
                            return b"AMD HSA\0".as_ptr() as *const ::core::ffi::c_char;
                        }
                        ELFOSABI_AMDGPU_PAL => {
                            return b"AMD PAL\0".as_ptr() as *const ::core::ffi::c_char;
                        }
                        ELFOSABI_AMDGPU_MESA3D => {
                            return b"AMD Mesa3D\0".as_ptr() as *const ::core::ffi::c_char;
                        }
                        _ => {}
                    },
                    EM_ARM => match osabi {
                        ELFOSABI_ARM => {
                            return b"ARM\0".as_ptr() as *const ::core::ffi::c_char;
                        }
                        ELFOSABI_ARM_FDPIC => {
                            return b"ARM FDPIC\0".as_ptr() as *const ::core::ffi::c_char;
                        }
                        _ => {}
                    },
                    EM_MSP430 | EM_MSP430_OLD | EM_VISIUM => match osabi {
                        ELFOSABI_STANDALONE => {
                            return dcgettext(
                                ::core::ptr::null::<::core::ffi::c_char>(),
                                b"Standalone App\0".as_ptr() as *const ::core::ffi::c_char,
                                LC_MESSAGES,
                            );
                        }
                        _ => {}
                    },
                    EM_TI_C6000 => match osabi {
                        ELFOSABI_C6000_ELFABI => {
                            return dcgettext(
                                ::core::ptr::null::<::core::ffi::c_char>(),
                                b"Bare-metal C6000\0".as_ptr() as *const ::core::ffi::c_char,
                                LC_MESSAGES,
                            );
                        }
                        ELFOSABI_C6000_LINUX => {
                            return b"Linux C6000\0".as_ptr() as *const ::core::ffi::c_char;
                        }
                        _ => {}
                    },
                    _ => {}
                }
            }
            snprintf(
                &raw mut buff as *mut ::core::ffi::c_char,
                ::core::mem::size_of::<[::core::ffi::c_char; 32]>(),
                dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"<unknown: %x>\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                ),
                osabi,
            );
            return &raw mut buff as *mut ::core::ffi::c_char;
        }
    };
}
