unsafe extern "C" fn get_lto_kind(mut kind: ::core::ffi::c_uint) -> *const ::core::ffi::c_char {
    match kind {
        0 => return b"DEF\0".as_ptr() as *const ::core::ffi::c_char,
        1 => return b"WEAKDEF\0".as_ptr() as *const ::core::ffi::c_char,
        2 => return b"UNDEF\0".as_ptr() as *const ::core::ffi::c_char,
        3 => return b"WEAKUNDEF\0".as_ptr() as *const ::core::ffi::c_char,
        4 => return b"COMMON\0".as_ptr() as *const ::core::ffi::c_char,
        _ => {}
    }
    static mut buffer: [::core::ffi::c_char; 30] = [0; 30];
    error(
        dcgettext(
            ::core::ptr::null::<::core::ffi::c_char>(),
            b"Unknown LTO symbol definition encountered: %u\n\0".as_ptr()
                as *const ::core::ffi::c_char,
            LC_MESSAGES,
        ),
        kind,
    );
    sprintf(
        &raw mut buffer as *mut ::core::ffi::c_char,
        b"<unknown: %u>\0".as_ptr() as *const ::core::ffi::c_char,
        kind,
    );
    return &raw mut buffer as *mut ::core::ffi::c_char;
}
