        printf(b"  \0".as_ptr() as *const ::core::ffi::c_char);
        print_vma(end, print_mode::FULL_HEX);
        printf(b"  \0".as_ptr() as *const ::core::ffi::c_char);
        print_vma(file_ofs, print_mode::FULL_HEX);
