unsafe extern "C" fn get_netbsd_elfcore_note_type(
    mut filedata: *mut Filedata,
    mut e_type: ::core::ffi::c_uint,
) -> *const ::core::ffi::c_char {
    static mut buff: [::core::ffi::c_char; 64] = [0; 64];
    match e_type {
        NT_NETBSDCORE_PROCINFO => {
            return dcgettext(
                ::core::ptr::null::<::core::ffi::c_char>(),
                b"NetBSD procinfo structure\0".as_ptr() as *const ::core::ffi::c_char,
                LC_MESSAGES,
            );
        }
        NT_NETBSDCORE_AUXV => {
            return dcgettext(
                ::core::ptr::null::<::core::ffi::c_char>(),
                b"NetBSD ELF auxiliary vector data\0".as_ptr() as *const ::core::ffi::c_char,
                LC_MESSAGES,
            );
        }
        NT_NETBSDCORE_LWPSTATUS => {
            return dcgettext(
                ::core::ptr::null::<::core::ffi::c_char>(),
                b"PT_LWPSTATUS (ptrace_lwpstatus structure)\0".as_ptr()
                    as *const ::core::ffi::c_char,
                LC_MESSAGES,
            );
        }
        _ => {
            if e_type < NT_NETBSDCORE_FIRSTMACH as ::core::ffi::c_uint {
                snprintf(
                    &raw mut buff as *mut ::core::ffi::c_char,
                    ::core::mem::size_of::<[::core::ffi::c_char; 64]>(),
                    dcgettext(
                        ::core::ptr::null::<::core::ffi::c_char>(),
                        b"Unknown note type: (0x%08x)\0".as_ptr() as *const ::core::ffi::c_char,
                        LC_MESSAGES,
                    ),
                    e_type,
                );
                return &raw mut buff as *mut ::core::ffi::c_char;
            }
        }
    }
    match (*filedata).file_header.e_machine as ::core::ffi::c_int {
        EM_OLD_ALPHA | EM_ALPHA | EM_SPARC | EM_SPARC32PLUS | EM_SPARCV9 => match e_type {
            32 => {
                return dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"PT_GETREGS (reg structure)\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                );
            }
            34 => {
                return dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"PT_GETFPREGS (fpreg structure)\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                );
            }
            _ => {}
        },
        EM_SH => match e_type {
            33 => {
                return dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"PT___GETREGS40 (old reg structure)\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                );
            }
            35 => {
                return dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"PT_GETREGS (reg structure)\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                );
            }
            37 => {
                return dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"PT_GETFPREGS (fpreg structure)\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                );
            }
            _ => {}
        },
        _ => match e_type {
            33 => {
                return dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"PT_GETREGS (reg structure)\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                );
            }
            35 => {
                return dcgettext(
                    ::core::ptr::null::<::core::ffi::c_char>(),
                    b"PT_GETFPREGS (fpreg structure)\0".as_ptr() as *const ::core::ffi::c_char,
                    LC_MESSAGES,
                );
            }
            _ => {}
        },
    }
    snprintf(
        &raw mut buff as *mut ::core::ffi::c_char,
        ::core::mem::size_of::<[::core::ffi::c_char; 64]>(),
        b"PT_FIRSTMACH+%d\0".as_ptr() as *const ::core::ffi::c_char,
        e_type.wrapping_sub(NT_NETBSDCORE_FIRSTMACH as ::core::ffi::c_uint),
    );
    return &raw mut buff as *mut ::core::ffi::c_char;
}
