unsafe extern "C" fn print_stapsdt_note(mut pnote: *mut Elf_Internal_Note) -> bool {
    let mut len: size_t = 0;
    let mut maxlen: size_t = 0;
    let mut addr_size: size_t = (if is_32bit_elf as ::core::ffi::c_int != 0 {
        4 as ::core::ffi::c_int
    } else {
        8 as ::core::ffi::c_int
    }) as size_t;
    let mut data: *mut ::core::ffi::c_char = (*pnote).descdata;
    let mut data_end: *mut ::core::ffi::c_char = (*pnote).descdata.offset((*pnote).descsz as isize);
    let mut pc: uint64_t = 0;
    let mut base_addr: uint64_t = 0;
    let mut semaphore: uint64_t = 0;
    let mut provider: *mut ::core::ffi::c_char = ::core::ptr::null_mut::<::core::ffi::c_char>();
    let mut probe: *mut ::core::ffi::c_char = ::core::ptr::null_mut::<::core::ffi::c_char>();
    let mut arg_fmt: *mut ::core::ffi::c_char = ::core::ptr::null_mut::<::core::ffi::c_char>();
    if ((*pnote).descsz as size_t) >= addr_size.wrapping_mul(3 as size_t) {
        pc = byte_get.expect("non-null function pointer")(
            data as *mut ::core::ffi::c_uchar,
            addr_size as ::core::ffi::c_uint,
        );
        data = data.offset(addr_size as isize);
        base_addr = byte_get.expect("non-null function pointer")(
            data as *mut ::core::ffi::c_uchar,
            addr_size as ::core::ffi::c_uint,
        );
        data = data.offset(addr_size as isize);
        semaphore = byte_get.expect("non-null function pointer")(
            data as *mut ::core::ffi::c_uchar,
            addr_size as ::core::ffi::c_uint,
        );
        data = data.offset(addr_size as isize);
        if data < data_end {
            maxlen = data_end.offset_from(data) as size_t;
            len = strnlen(data, maxlen);
            if len < maxlen {
                provider = data;
                data = data.offset(len.wrapping_add(1 as size_t) as isize);
                if data < data_end {
                    maxlen = data_end.offset_from(data) as size_t;
                    len = strnlen(data, maxlen);
                    if len < maxlen {
                        probe = data;
                        data = data.offset(len.wrapping_add(1 as size_t) as isize);
                        if data < data_end {
                            maxlen = data_end.offset_from(data) as size_t;
                            len = strnlen(data, maxlen);
                            if len < maxlen {
                                arg_fmt = data;
                                data = data.offset(len.wrapping_add(1 as size_t) as isize);
                                printf(
                                    dcgettext(
                                        ::core::ptr::null::<::core::ffi::c_char>(),
                                        b"    Provider: %s\n\0".as_ptr()
                                            as *const ::core::ffi::c_char,
                                        LC_MESSAGES,
                                    ),
                                    provider,
                                );
                                printf(
                                    dcgettext(
                                        ::core::ptr::null::<::core::ffi::c_char>(),
                                        b"    Name: %s\n\0".as_ptr() as *const ::core::ffi::c_char,
                                        LC_MESSAGES,
                                    ),
                                    probe,
                                );
                                printf(dcgettext(
                                    ::core::ptr::null::<::core::ffi::c_char>(),
                                    b"    Location: \0".as_ptr() as *const ::core::ffi::c_char,
                                    LC_MESSAGES,
                                ));
                                print_vma(pc, print_mode::FULL_HEX);
                                printf(dcgettext(
                                    ::core::ptr::null::<::core::ffi::c_char>(),
                                    b", Base: \0".as_ptr() as *const ::core::ffi::c_char,
                                    LC_MESSAGES,
                                ));
                                print_vma(base_addr, print_mode::FULL_HEX);
                                printf(dcgettext(
                                    ::core::ptr::null::<::core::ffi::c_char>(),
                                    b", Semaphore: \0".as_ptr() as *const ::core::ffi::c_char,
                                    LC_MESSAGES,
                                ));
                                print_vma(semaphore, print_mode::FULL_HEX);
                                printf(b"\n\0".as_ptr() as *const ::core::ffi::c_char);
                                printf(
                                    dcgettext(
                                        ::core::ptr::null::<::core::ffi::c_char>(),
                                        b"    Arguments: %s\n\0".as_ptr()
                                            as *const ::core::ffi::c_char,
                                        LC_MESSAGES,
                                    ),
                                    arg_fmt,
                                );
                                return data == data_end;
                            }
                        }
                    }
                }
            }
        }
    }
    printf(dcgettext(
        ::core::ptr::null::<::core::ffi::c_char>(),
        b"  <corrupt - note is too small>\n\0".as_ptr() as *const ::core::ffi::c_char,
        LC_MESSAGES,
    ));
    error(dcgettext(
        ::core::ptr::null::<::core::ffi::c_char>(),
        b"corrupt stapdt note - the data size is too small\n\0".as_ptr()
            as *const ::core::ffi::c_char,
        LC_MESSAGES,
    ));
    return r#false != 0;
}
unsafe extern "C" fn print_fdo_note(mut pnote: *mut Elf_Internal_Note) -> bool {
    if (*pnote).descsz > 0 as ::core::ffi::c_ulong
        && (*pnote).r#type == FDO_PACKAGING_METADATA as ::core::ffi::c_ulong
    {
        printf(
            dcgettext(
                ::core::ptr::null::<::core::ffi::c_char>(),
                b"    Packaging Metadata: %.*s\n\0".as_ptr() as *const ::core::ffi::c_char,
                LC_MESSAGES,
            ),
            (*pnote).descsz as ::core::ffi::c_int,
            (*pnote).descdata,
        );
        return r#true != 0;
    }
    if (*pnote).descsz > 0 as ::core::ffi::c_ulong
        && (*pnote).r#type == FDO_DLOPEN_METADATA as ::core::ffi::c_ulong
    {
        printf(
            dcgettext(
                ::core::ptr::null::<::core::ffi::c_char>(),
                b"    Dlopen Metadata: %.*s\n\0".as_ptr() as *const ::core::ffi::c_char,
                LC_MESSAGES,
            ),
            (*pnote).descsz as ::core::ffi::c_int,
            (*pnote).descdata,
        );
        return r#true != 0;
    }
    return r#false != 0;
}
